using Microsoft.Agents.AI;
using Microsoft.Agents.AI.Abstractions;
using Microsoft.Extensions.AI;

var agentType = typeof(ChatClientAgent);
Console.WriteLine("=== Constructors ===");
foreach (var c in agentType.GetConstructors())
    Console.WriteLine($"  ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");

Console.WriteLine("\n=== Properties ===");
foreach (var p in agentType.GetProperties())
    Console.WriteLine($"  {p.PropertyType.Name} {p.Name}");

Console.WriteLine("\n=== Methods ===");
foreach (var m in agentType.GetMethods().Where(m => m.DeclaringType == agentType || m.DeclaringType!.Name.Contains("Agent")))
    Console.WriteLine($"  {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))}) -> {m.ReturnType.Name}");

Console.WriteLine("\n=== RunOptions ===");
foreach (var p in typeof(RunOptions).GetProperties())
    Console.WriteLine($"  {p.PropertyType} {p.Name}");

Console.WriteLine("\n=== AgentResponseUpdate ===");
foreach (var p in typeof(AgentResponseUpdate).GetProperties())
    Console.WriteLine($"  {p.PropertyType.Name} {p.Name}");
PROG

