using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var agentType = typeof(ChatClientAgent);
Console.WriteLine("=== Constructors ===");
foreach (var c in agentType.GetConstructors())
    Console.WriteLine($"  ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType} {p.Name}"))})" );

Console.WriteLine("\n=== Properties ===");
foreach (var p in agentType.GetProperties())
    Console.WriteLine($"  {p.PropertyType} {p.Name}");

Console.WriteLine("\n=== Methods (own + base agent) ===");
foreach (var m in agentType.GetMethods(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance)
    .Where(m => m.DeclaringType != typeof(object)))
    Console.WriteLine($"  {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))}) -> {m.ReturnType}");

Console.WriteLine("\n=== AgentRunOptions ===");
foreach (var p in typeof(AgentRunOptions).GetProperties())
    Console.WriteLine($"  {p.PropertyType} {p.Name}");

Console.WriteLine("\n=== AgentResponseUpdate ===");
foreach (var p in typeof(AgentResponseUpdate).GetProperties())
    Console.WriteLine($"  {p.PropertyType} {p.Name}");

