using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Register tools ---
var notebook = new Notebook();
var webSearcher = new WebSearcher();

List<AITool> tools =
[
    AIFunctionFactory.Create(webSearcher.SearchWebAsync),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
];

// --- Create the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly and
        produce a well-organized summary.

        Follow this workflow:
        1. Break the topic into 2-3 key subtopics or questions.
        2. Use the SearchWeb tool to find information on each subtopic.
        3. After each search, use SaveNote to record the key findings with a
           descriptive title.
        4. Once you have gathered enough information, use GetNotes to review
           all your research notes.
        5. Produce a final, well-structured summary with sections, citing the
           sources you found.

        Be concise but thorough. Always attribute information to its source.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    tools: tools);

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (MAF + MEAI)    ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and produce a comprehensive summary: {topic}",
    session,
    runOptions))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine("\n\n✅ Research complete.");

// ─── Tool Implementations ────────────────────────────────────────────

/// <summary>Provides web search capabilities via DuckDuckGo.</summary>
sealed class WebSearcher
{
    private readonly HttpClient _http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    [Description("Search the web for information. Returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await _http.GetStringAsync(url, cancellationToken);

            var results = ParseDuckDuckGoResults(html);
            if (results.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            Console.WriteLine($"  ✓ Found {results.Count} results");
            return string.Join("\n\n", results.Select((r, i) =>
                $"[{i + 1}] {r.Title}\n    URL: {r.Url}\n    {r.Snippet}"));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseDuckDuckGoResults(string html)
    {
        var results = new List<SearchResult>();

        // Parse result blocks from DuckDuckGo HTML
        var snippetSplits = html.Split("class=\"result__snippet\"", StringSplitOptions.None);
        var titleSplits = html.Split("class=\"result__a\"", StringSplitOptions.None);

        var count = Math.Min(titleSplits.Length - 1, snippetSplits.Length - 1);
        count = Math.Min(count, 5); // Limit to top 5

        for (int i = 0; i < count; i++)
        {
            var title = ExtractText(titleSplits[i + 1]);
            var snippet = ExtractText(snippetSplits[i + 1]);
            var url = ExtractHref(titleSplits[i + 1]);

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new(title, url, snippet));
            }
        }

        return results;
    }

    private static string ExtractText(string htmlFragment)
    {
        // Get text content until closing tag
        var end = htmlFragment.IndexOf('<');
        var start = htmlFragment.IndexOf('>');
        if (start < 0) return "";
        start++;
        if (end < 0 || end < start) end = Math.Min(htmlFragment.Length, start + 300);
        var text = htmlFragment[start..end];
        // Strip remaining HTML tags
        text = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", "");
        return System.Net.WebUtility.HtmlDecode(text).Trim();
    }

    private static string ExtractHref(string htmlFragment)
    {
        var match = System.Text.RegularExpressions.Regex.Match(
            htmlFragment, @"href=""([^""]+)""");
        if (!match.Success) return "(no URL)";
        var href = System.Net.WebUtility.UrlDecode(match.Groups[1].Value);
        // DuckDuckGo wraps URLs in a redirect; extract the actual URL
        var uddg = System.Text.RegularExpressions.Regex.Match(href, @"uddg=([^&]+)");
        return uddg.Success
            ? Uri.UnescapeDataString(uddg.Groups[1].Value)
            : href;
    }

    private record SearchResult(string Title, string Url, string Snippet);
}

/// <summary>In-memory notebook for storing research findings.</summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a research note. Use this to record key findings from searches.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The research findings to save")] string content)
    {
        _notes.Add((title, content));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Retrieve all saved research notes to review before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        Console.WriteLine($"  📖 Reviewing {_notes.Count} note(s)");
        return string.Join("\n\n---\n\n", _notes.Select((n, i) =>
            $"Note #{i + 1}: {n.Title}\n{n.Content}"));
    }
}

